/* Entrada manual demonstrativa: sem upload, OCR, pagamento ou consumo real. */
let intake={step:1,scenario:null,files:[]},creditBalance=8,manualEntries=[];
const manualSamples={ready:{id:'EXT-0042',bl:'DEMOEXT0042',agent:'Agente Delta',reference:'Proposta Delta 184 · v2',amount:2000,billed:2180},clean:{id:'EXT-0043',bl:'DEMOEXT0043',agent:'Agente Delta',reference:'Proposta Delta 185 · v1',amount:2000,billed:2000}};
function intakeSample(){return manualSamples[intake.scenario==='clean'?'clean':'ready'];}
function manualMessage(m){return `Solicitamos a revisão da fatura ${m.id}, vinculada ao BL ${m.bl}.

A referência ${m.reference}, acompanhada do aceite, registra USD 2.000 para o frete. A fatura cobra USD 2.180 pelo mesmo serviço, diferença de USD 180.

Solicitamos a retificação da cobrança ou a referência aprovada que justifique a diferença. A proposta, o aceite e a cobrança estão reunidos no dossiê.

Agradecemos o retorno.`;}
function manualSources(m){return [['Proposta comercial','Frete: USD 2.000 · moeda USD · mesma base de cobrança. Referência: '+m.reference],['Aceite da proposta','Aceite vinculado à referência '+m.reference+'. Nenhuma alteração posterior aprovada neste exemplo.'],['Fatura de frete',`${m.id} · BL ${m.bl} · ${money(m.billed)} · emissor ${m.agent}.`]];}
function intakeHeader(){return `<nav class="breadcrumb"><a href="#auditoria">Auditoria</a><span>›</span><span>Auditar outro embarque</span></nav><div class="heading"><div><h1>Auditar outro embarque</h1><p>Use o que já está no Centrix ou traga os documentos de uma operação anterior.</p></div>${tag(creditBalance+' créditos de exemplo','blue')}</div>`;}
function intakePage(){return `${intakeHeader()}<ol class="intake-steps" aria-label="Etapas da entrada"><li class="${intake.step===1?'active':''}" ${intake.step===1?'aria-current="step"':''}>1. Documentos e vínculo</li><li class="${intake.step===2?'active':''}" ${intake.step===2?'aria-current="step"':''}>2. Escopo e créditos</li><li>3. Resultado na plataforma</li></ol>${intake.step===2?intakeReview():intakeStart()}<p class="small gap">Demonstração de experiência. Saldo, custo e resultados são ilustrativos e duram apenas nesta sessão. A regra comercial ainda precisa ser definida.</p>`;}
function intakeStart(){return `<div class="intake-grid"><section class="panel"><div class="panel-head"><div>${tag('Jornada conectada','green')}<h2 class="gap">O embarque já está no Centrix?</h2><p>Abra a auditoria existente e acrescente somente o que estiver faltando.</p></div></div><div class="panel-body"><label class="field">Localizar embarque<select id="intake-existing">${records.map(s=>`<option value="${s.id}">${ref(s)} · ${s.route} · ${s.bl}</option>`).join('')}</select></label>${btn('Usar embarque cadastrado','intake-existing','','','link')}<p class="small gap">Documentos, versões e histórico reaproveitados. Nenhuma nova auditoria avulsa ou consumo de crédito nesta entrada.</p></div></section><section class="panel intake-upload"><div class="panel-head"><div>${tag('Entrada manual','blue')}<h2 class="gap">A operação aconteceu fora daqui?</h2><p>Adicione os documentos juntos. A proposta e o aceite podem vir de fora do Centrix.</p></div></div><div class="panel-body"><div class="upload-area">${icon('file')}<strong>Comece com o combinado e o cobrado</strong><p>Proposta ou tabela + aceite + fatura de frete.<br>BL e booking ajudam a identificar o embarque.</p><label class="btn primary">Selecionar documentos<input id="intake-files" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.eml,.msg,.docx,.xlsx" aria-label="Selecionar documentos para auditoria"></label><small>PDF, imagem, e-mail, Word ou Excel</small></div>${intake.files.length?`<div class="notice gap"><p><strong>${intake.files.length} arquivo(s) selecionado(s) localmente</strong>${intake.files.map(f=>escapeHTML(f)).join('<br>')}<br><br>A extração de arquivos reais ainda não está conectada neste protótipo. Nenhum arquivo foi enviado ou crédito consumido. Explore o fluxo com os exemplos abaixo.</p></div>`:''}<p class="small gap">A identificação e a checagem inicial não consomem créditos. O custo aparece antes de executar a auditoria.</p><details class="gap" open><summary>Explorar com documentos de exemplo</summary><div class="intake-examples">${btn('Conjunto completo','intake-example','data-scenario="ready"','small')}${btn('Falta o aceite','intake-example','data-scenario="missing"','small')}${btn('Embarque já cadastrado','intake-example','data-scenario="duplicate"','small')}${btn('Cobrança conforme','intake-example','data-scenario="clean"','small')}</div></details></div></section></div>`;}
function intakeReview(){
 const m=intakeSample(),missing=intake.scenario==='missing',duplicate=intake.scenario==='duplicate',existing=manualEntries.find(x=>x.id===m.id);
 if(duplicate)return `<section class="panel"><div class="panel-body">${tag('Vínculo encontrado','green')}<h2 class="gap">Este embarque já está na sua plataforma</h2><p class="gap">O BL ALPHA260811 corresponde ao EMB-2026-0011. A cotação aprovada, os documentos e a conferência já estão disponíveis.</p><div class="notice green gap"><p><strong>Reaproveitar, sem duplicar.</strong>Nenhum crédito será consumido para abrir a auditoria existente. Um documento novo deve complementar esse mesmo histórico.</p></div><div class="intake-actions"><a class="btn primary" href="#auditoria/0011/documentos">Abrir documentos do embarque →</a>${btn('Voltar','intake-back')}</div></div></section>`;
 if(existing)return `<section class="panel"><div class="panel-body">${tag('Auditoria já disponível','green')}<h2 class="gap">Você já auditou estes documentos</h2><p class="gap">${m.id} · BL ${m.bl}. Abrir o resultado e exportar novamente não consome outro crédito.</p><div class="intake-actions"><a class="btn primary" href="#auditoria/manual/${m.id}">Abrir resultado →</a>${btn('Voltar','intake-back')}</div></div></section>`;
 return `<div class="intake-review-grid"><section class="panel"><div class="panel-head"><div><h2>Uma operação identificada</h2><p>${m.bl} · ${m.agent} · origem externa</p></div>${tag('Pré-checagem · sem consumo','blue')}</div><div class="panel-body"><p>Os documentos apontam para o mesmo embarque. Ele ficará na Auditoria, sem exigir uma cotação ou um fluxo operacional retroativo.</p><div class="intake-source"><div><strong>${m.reference}</strong><small>Condição comercial · USD · frete</small></div>${tag('Disponível','green')}</div><div class="intake-source"><div><strong>Aceite da condição comercial</strong><small>${missing?'Falta comprovar qual condição foi autorizada.':'E-mail de aceite associado à proposta.'}</small></div>${tag(missing?'Falta fonte':'Vinculado',missing?'blue':'green')}</div><div class="intake-source"><div><strong>Fatura de frete · ${m.id}</strong><small>Identificação pelo BL ${m.bl}</small></div>${tag('Disponível','green')}</div><div class="notice ${missing?'':'green'} gap"><p><strong>${missing?'Falta uma evidência para comparar com segurança.':'Base suficiente para a conferência financeira.'}</strong>${missing?'Não é necessário reenviar a proposta nem a fatura. Complemente apenas o aceite da referência comercial.':'Condição, aceite e cobrança estão disponíveis. Nenhuma nova aprovação dos documentos é necessária.'}</p></div>${missing?btn('Adicionar aceite de exemplo','intake-complete','','primary gap'):''}<details class="gap"><summary>O que ficará fora desta análise</summary><p class="gap">Performance, transit time e responsabilidade por atrasos: não há eventos realizados suficientes neste conjunto. Nenhuma conclusão operacional ou score será presumido.</p></details></div></section><aside class="panel intake-cost"><div class="panel-body"><div class="eyebrow">Auditoria avulsa</div><h2>1 crédito <span class="small">/ embarque</span></h2><p class="gap">Conferência financeira de todos os itens da cobrança, evidências e caso pronto quando houver divergência.</p><dl class="facts gap"><div><dt>Saldo demonstrativo</dt><dd>${creditBalance} créditos</dd></div><div><dt>Consumo nesta execução</dt><dd>${missing?'Bloqueado · 0 créditos':'1 crédito'}</dd></div><div><dt>Saldo após executar</dt><dd>${missing?creditBalance:creditBalance-1} créditos</dd></div></dl><p class="small gap"><strong>Mesmo se a cobrança estiver correta, a análise consome 1 crédito.</strong> Nesse caso, você recebe a conferência documentada. Reabrir e exportar esse resultado não consome novamente.</p>${btn('Auditar por 1 crédito','intake-run',missing||creditBalance<1?'disabled':'','primary gap')}<p class="small gap">${missing?'Complete a fonte para liberar a execução. Nenhum consumo até lá.':'Ao clicar, você autoriza somente o consumo simulado indicado acima.'}</p></div></aside></div><div class="intake-actions">${btn('Voltar aos documentos','intake-back')}<a class="btn text" href="#auditoria">Voltar à Auditoria · manter rascunho</a></div>`;
}
function manualPortfolio(){return `${manualEntries.length||intake.step===2?`<section class="panel gap"><div class="panel-head"><div><h2>Adicionadas manualmente</h2><p>Operações externas reunidas na mesma área de Auditoria.</p></div>${tag(creditBalance+' créditos de exemplo','blue')}</div><div class="panel-body">${intake.step===2&&!manualEntries.some(m=>m.id===intakeSample().id)&&intake.scenario!=='duplicate'?`<div class="intake-source"><div><strong>Entrada em rascunho</strong><small>${intake.scenario==='missing'?'Falta aceite da proposta':'Pronta para conferir escopo e custo'} · nenhum crédito consumido</small></div><a class="btn small" href="#auditoria/entrada">Continuar →</a></div>`:''}${manualEntries.map(m=>`<div class="intake-source"><div><strong>${m.id} · ${m.bl}</strong><small>${m.billed>m.amount?money(m.billed-m.amount)+' para questionar':'Conferido · sem divergência'} · origem externa · 1 crédito consumido</small></div><a class="btn small" href="#auditoria/manual/${m.id}">Ver resultado →</a></div>`).join('')}</div></section>`:''}`;}
function manualResult(id){const m=manualEntries.find(x=>x.id===id);if(!m)return `${intakeHeader()}<div class="notice"><p>Este resultado não está disponível nesta sessão. Use os documentos de exemplo para executar uma auditoria.</p></div><a class="btn gap" href="#auditoria/entrada">Adicionar documentos →</a>`;const diff=m.billed-m.amount;return `<nav class="breadcrumb"><a href="#auditoria">Auditoria</a><span>›</span><span>${m.id}</span></nav><div class="heading"><div><h1>${diff?'Caso pronto':'Conferência concluída'} · ${m.id}</h1><p>BL ${m.bl} · ${m.agent} · origem externa</p></div>${tag('1 crédito consumido · exemplo','blue')}</div><div class="notice ${diff?'amber':'green'}"><p><strong>${diff?money(diff)+' para questionar':'Nenhuma divergência financeira identificada.'}</strong>${diff?'A diferença está fundamentada na proposta e no aceite adicionados. Não representa valor recuperado.':'A cobrança coincide com a condição aprovada. O resultado e suas evidências ficam disponíveis aqui.'} Reabrir e exportar não consome créditos novamente.</p></div><div class="intake-review-grid gap"><section class="panel"><div class="panel-head"><h2>${diff?'O caso já está montado':'Registro da conferência'}</h2>${btn(diff?'Baixar e-mail + dossiê':'Baixar conferência','manual-export',`data-manual="${m.id}"`,'primary','down')}</div><div class="panel-body"><div class="table-wrap"><table><thead><tr><th>Item</th><th>Aprovado</th><th>Cobrado</th><th>Diferença</th></tr></thead><tbody><tr><td>Frete</td><td>${money(m.amount)}</td><td>${money(m.billed)}</td><td>${money(diff)}</td></tr></tbody></table></div><p class="small gap">${m.reference} + aceite · mesma moeda e base de cobrança. Tolerância ilustrativa: 5%. Nenhuma alteração posterior aprovada localizada nos exemplos.</p>${diff?`<label class="field">Mensagem pronta para ${m.agent}<textarea id="manual-message" data-manual="${m.id}" style="min-height:260px">${escapeHTML(m.message||manualMessage(m))}</textarea></label><p class="small">O rascunho não é enviado pelo Centrix. Confirme o destinatário no seu e-mail.</p>`:''}<div id="manual-export-status" class="source-label gap">${m.exported?'Material exportado · envio não confirmado.':''}</div></div></section><aside class="panel"><div class="panel-body"><h3>Seu processo fica aqui</h3><dl class="facts gap"><div><dt>Origem</dt><dd>Documentos adicionados manualmente</dd></div><div><dt>Referência</dt><dd>${m.reference}</dd></div><div><dt>Escopo auditado</dt><dd>Financeiro · performance não coberta</dd></div><div><dt>Saldo restante</dt><dd>${creditBalance} créditos de exemplo</dd></div></dl><a class="btn text gap" href="#auditoria">Voltar à Auditoria →</a></div></aside></div><section class="panel gap"><div class="panel-head"><h2>Fontes e trilha desta entrada</h2></div><div class="panel-body"><details><summary>Documentos de origem externa · 3 fontes</summary>${manualSources(m).map(([title,body])=>`<div class="intake-source"><div><strong>${title}</strong><small>${body}</small></div></div>`).join('')}<p class="small gap">Representações demonstrativas. No produto, cada referência abre o arquivo original anexado.</p></details><details open class="gap"><summary>O que aconteceu automaticamente</summary><ol class="text-list"><li>Proposta, aceite e fatura identificados como documentos de uma mesma operação externa, pelo BL ${m.bl}.</li><li>Pré-checagem confirmou a base financeira disponível. Performance ficou fora por ausência de eventos.</li><li>Usuário autorizou a execução por 1 crédito simulado. O consumo pertence a esta auditoria, não a cada item ou download.</li><li>${diff?'Frete aprovado de USD 2.000 comparado com USD 2.180 cobrados; diferença de USD 180 (9%) identificada.':'Frete aprovado e cobrado de USD 2.000 comparados; nenhuma diferença identificada.'}</li><li>${diff?'Referência e aceite sustentaram o pedido de revisão; mensagem e evidências reunidas.':'Conferência conforme documentada, sem tarefa de aprovação ou contestação.'}</li>${m.exported?'<li>Material exportado. Envio e resposta não confirmados.</li>':''}</ol></details></div></section>`;}
function manualDossier(m){return `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Auditoria ${m.id}</title><style>body{font:16px/1.5 Arial;max-width:800px;margin:40px auto;padding:20px;color:#272b43}pre{white-space:pre-wrap;background:#f4f5fa;padding:18px}</style><h1>Auditoria ${m.id}</h1><p>DEMONSTRAÇÃO · documentos e créditos ilustrativos</p><p>BL ${m.bl}. Origem externa. Escopo financeiro. Performance não coberta.</p><p>Aprovado: ${money(m.amount)}. Cobrado: ${money(m.billed)}. Diferença: ${money(m.billed-m.amount)}. Não representa recuperação.</p>${m.billed>m.amount?'<h2>Mensagem</h2><pre>'+escapeHTML(m.message||manualMessage(m))+'</pre>':'<h2>Conferência conforme</h2><p>Valores coincidentes nas fontes disponíveis.</p>'}<h2>Evidências demonstrativas</h2>${manualSources(m).map(([title,body])=>'<h3>'+title+'</h3><p>'+body+'</p>').join('')}<p>Consumo simulado: 1 crédito. Exportação não confirma envio. A implementação deve anexar as fontes originais.</p></html>`;}
function manualEmail(m){const boundary='manual-centrix-'+m.id;const part=(type,name,body)=>`--${boundary}\r\nContent-Type: ${type}; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n${name?'Content-Disposition: attachment; filename="'+name+'"\r\n':''}\r\n${base64utf8(body).match(/.{1,76}/g).join('\r\n')}\r\n`;return `X-Unsent: 1\r\nMIME-Version: 1.0\r\nSubject: Revisao de cobranca | ${m.id}\r\nContent-Type: multipart/mixed; boundary="${boundary}"\r\n\r\n${part('text/plain','',m.message||manualMessage(m))}${part('text/html','Dossie-'+m.id+'-DEMO.html',manualDossier(m))}--${boundary}--\r\n`;}
document.addEventListener('change',e=>{if(e.target.id==='intake-files'){intake.files=[...e.target.files].map(f=>f.name);render();}});
document.addEventListener('input',e=>{if(e.target.id==='manual-message'){const m=manualEntries.find(x=>x.id===e.target.dataset.manual);if(m)m.message=e.target.value;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){
 case 'intake-existing':location.hash='#auditoria/'+$('#intake-existing').value+'/documentos';break;
 case 'intake-example':intake={step:2,scenario:b.dataset.scenario,files:[]};render();break;
 case 'intake-back':intake.step=1;render();break;
 case 'intake-complete':intake.scenario='ready';render();toast('Aceite demonstrativo vinculado. Nenhum crédito consumido.');break;
 case 'intake-run':{if(!['ready','clean'].includes(intake.scenario)||intake.step!==2)return;const sample=intakeSample(),existing=manualEntries.find(x=>x.id===sample.id);if(existing){location.hash='#auditoria/manual/'+existing.id;return;}if(creditBalance<1)return;creditBalance-=1;manualEntries.push({...sample});intake.step=1;location.hash='#auditoria/manual/'+sample.id;toast('Auditoria demonstrativa concluída. 1 crédito simulado consumido.');break;}
 case 'manual-export':{const m=manualEntries.find(x=>x.id===b.dataset.manual);if(!m)return;if($('#manual-message'))m.message=$('#manual-message').value;downloadFile('Auditoria-'+m.id+'-DEMO.'+(m.billed>m.amount?'eml':'html'),m.billed>m.amount?manualEmail(m):manualDossier(m),m.billed>m.amount?'message/rfc822':'text/html;charset=utf-8');m.exported=true;render();toast('Material demonstrativo baixado. Nenhum envio ou novo consumo.');break;}
 case 'confirm-reset':intake={step:1,scenario:null,files:[]};manualEntries=[];creditBalance=8;break;
}});
